from common8 import *
import csv

def main():
 guard()
 with (D/'TASK_ENTRY_ANALYSIS.csv').open() as f:entries=list(csv.DictReader(f))
 selected=[r for r in entries if r['split']=='dev' and r['CV_seed']=='42'];assert len(selected)==72;table('ADJACENT_TASK_SUMMARY.csv',selected)
 ix={(r['family'],r['task'],r['representation'],r['policy']):r for r in selected}
 def fmt(r):return f"{float(r['estimate']):+.4f} [{float(r['ci_low']):+.4f}, {float(r['ci_high']):+.4f}]"
 lines=['## Every eligible transition across all six tasks','','The table uses the fixed layer16/seed42 display, with paired pointwise exploratory 95% intervals in raw AUROC units. These correlated cells are descriptive, with no family-wide significance claim. [Complete anchor summary](ADJACENT_TASK_SUMMARY.csv) includes final norm, exact logical IDs and declarations; [task-entry analysis](TASK_ENTRY_ANALYSIS.csv) includes all three CV seeds and the separately labeled H3 exploratory test. Full-layer effects remain in `plot_data/`.','','| Transition | Task | Supplied-config category | Refitted ΔAUROC [95% interval] | Unchanged-base ΔAUROC [95% interval] |','|---|---|---|---:|---:|']
 for family in ['R4_minus_R3','R5_minus_R4','R6_minus_R5']:
  for task in TASKS:
   a=ix[family,task,'decoder.layers.16','independent_refit'];b=ix[family,task,'decoder.layers.16','fixed_original_base'];lines.append('| '+family.replace('_minus_',' − ')+' | '+task+' | '+a['entry_category']+' | '+fmt(a)+' | '+fmt(b)+' |')
 splice=[ix['R4_minus_R3','gue_splice_reconstructed','decoder.layers.16',p] for p in POLICIES];lines+=['','Splice changes before declaration in the supplied R4 retain configuration: layer16/seed42 R4 − R3 is '+fmt(splice[0])+' refitted and '+fmt(splice[1])+' with the unchanged-base readout. The refitted interval is inconclusive if it contains zero. These are existing eligible adjacent comparisons, not a newly added inferential family. Exact evidence IDs: '+', '.join('`'+r['logical_id']+'`' for r in splice)+'. Unknown realized training exposure is not absence of exposure.','','The full profiles show representation and policy dependence rather than monotonic improvement across the retain-set order. All 25 block profiles and final norm are displayed for every supplied checkpoint, task and CV seed. Refitted and unchanged-base panels use comparable axes. The final norm is a separate representation, not a 26th block. [Readout-policy summary](READOUT_POLICY_SUMMARY.csv) reports descriptive point gaps and preserves their lack of a policy-gap confidence interval. Matched base/R1/composition/4-mer panels retain both favorable and adverse results; no control was fitted here.','','Actual causal-LM changes need separate interpretation. The splice transition improves LM NLL while its final-norm classifier interval is inconclusive; mouse R6 − R5 worsens LM NLL and several readout settings. These observations do not identify training mechanisms or establish forgetting.','','']
 text=(D/'ANALYSIS.md').read_text();assert '## Every eligible transition across all six tasks' not in text;text=text.replace('## Methods and evidence','\n'.join(lines)+'## Methods and evidence')
 replacements={'releases390':'releases 390','All390':'All 390','All3900':'All 3,900','all26':'all 26','all three':'all three','paired2000':'paired 2,000','vectors,24.6M':'vectors, 24.6M','frozen30':'frozen 30','used480':'used 480','cover16380':'cover 16,380','and70':'and 70','rows/32.76M':'rows / 32.76M','rows/140000':'rows / 140,000','exact33684':'exact 33,684','comprises4934':'comprises 4,934','+12300':'+ 12,300','and16450':'and 16,450','A06,12300':'A06, 12,300','approved1092':'approved 1,092','and7 LM':'and 7 LM','missing468':'missing 468','retain10948':'retain 10,948','remain unchanged. No':'remain unchanged. No','preserve float64':'preserve float64'}
 for old,new in replacements.items():text=text.replace(old,new)
 publish('ANALYSIS.md',text);print(json.dumps({'status':'PASS','task_edge_anchor_rows':72,'new_inferential_families':0,'science_repeated':0}))
if __name__=='__main__':main()
